"use strict";
let experienceZone='';
const zonePicker=tideEntranceBase,zoneStoryEntrance=renderPhoneEntrance,zoneStoryWorkbench=renderWorkbench,zoneScreen=phoneScreen;
const experienceStates={};
try{const p=JSON.parse(localStorage.getItem('olddays-experience-states')||'{}');for(const k of ['phone','pc','story'])if(p[k]&&typeof p[k]==='object')experienceStates[k]=p[k];}catch{}
let zoneStoryFlags=[tide.active,campus.started,mystery.started,mystery.paused];
tide.active=false;campus.started=false;mystery.started=false;mystery.paused=true;
function experienceSave(){if(!experienceZone)return;experienceStates[experienceZone]={phone:JSON.parse(JSON.stringify(phoneState)),date,entered:deskEntered,view:tideView,query:ucQuery,content:ucContent,website:deskWebsite?.url||'',java:pocketJavaChoice,track:memoryTrack};if(experienceZone==='story'){zoneStoryFlags=[tide.active,campus.started,mystery.started,mystery.paused];tideSave();}try{localStorage.setItem('olddays-experience-states',JSON.stringify(experienceStates));}catch{}}
function experienceNav(){return '<nav class="experience-nav" aria-label="体验分区"><button data-experience="">← 总入口</button>'+[['phone','口袋时光'],['pc','重连旧网'],['story','旧巷来客']].map(([id,t])=>'<button data-experience="'+id+'" aria-current="'+(experienceZone===id?'page':'false')+'">'+t+'</button>').join('')+'<button data-save-open>▣ 存档盒</button></nav>';}
function restoreExperiencePhone(p){if(!p||!Object.hasOwn(phoneModels,p.model))return false;phoneState.model=p.model;phoneState.app=phoneApps.some(a=>a[0]===p.app)||p.app==='snake'?p.app:'home';phoneState.wallpaper=['blue','sunset','stars','green'].includes(p.wallpaper)?p.wallpaper:'blue';phoneState.wallpaperImage=['campus','portrait','naruto','onepiece'].includes(p.wallpaperImage)?p.wallpaperImage:'';phoneState.draft=typeof p.draft==='string'?p.draft.slice(0,160):'';phoneState.sent=Array.isArray(p.sent)?p.sent.filter(r=>r&&typeof r.text==='string'&&typeof r.reply==='string').slice(-12).map(r=>({text:r.text.slice(0,160),reply:r.reply.slice(0,240),stamp:typeof r.stamp==='string'?r.stamp.slice(0,24):'',claimed:r.claimed===true})):[];phoneState.book=readingShelf().some(b=>b.id===p.book)?p.book:null;for(const k of ['page','film','chapter'])phoneState[k]=Number.isSafeInteger(p[k])&&p[k]>=0&&p[k]<10000?p[k]:0;phoneState.article=Number.isSafeInteger(p.article)&&p.article>=0&&p.article<1000?p.article:null;phoneState.captureBusy=false;return true;}
function chooseExperience(zone){if(!['','phone','pc','story'].includes(zone))return false;experienceSave();blenderWorldDispose?.();document.querySelector('#modal')?.close();pocketJavaReleaseAll();document.querySelector('#retro-audio')?.pause?.();document.body.classList.remove('pocket-expanded','pocket-landscape','exploration-open');experienceZone=zone;const s=experienceStates[zone];if(s?.phone)restoreExperiencePhone(s.phone);if(Number.isInteger(s?.track)&&s.track>=0&&s.track<memoryTracks.length){memoryTrack=s.track;document.querySelector('#retro-audio').src='audio/'+memoryTracks[memoryTrack].id+'.mp3';}if([...pocketClassicGames,...pocketJavaGames,...systemJavaTools].some(g=>g.id===s?.java))pocketJavaChoice=s.java;if(s?.date&&validTravelDate(s.date))date=s.date;if(!s){phoneState.article=null;phoneState.page=0;if(zone==='phone'||zone==='pc'){phoneState.sent=[];phoneState.draft='';phoneState.book=null;phoneState.chapter=0;}}tideView=zone==='story'&&typeof s?.view==='string'?s.view:'';ucQuery=typeof s?.query==='string'?s.query:'';ucContent=typeof s?.content==='string'?s.content:'';deskWebsite=(typeof siteCatalog==='undefined'?[]:siteCatalog).flatMap(g=>g.sites).find(site=>site.url===s?.website)||null;if(ucContent==='web'&&!deskWebsite)ucContent='';campusPanel='';mysteryPanel='';visitMode=zone==='pc'?'pc':'phone';phoneWebLayout=zone==='pc'?'desktop':'mobile';if(zone==='story'){[tide.active,campus.started,mystery.started,mystery.paused]=zoneStoryFlags;deskEntered=false;}else{tide.active=false;campus.started=false;mystery.started=false;mystery.paused=true;deskEntered=zone==='pc'||zone==='phone'&&s?.entered===true;if(!s)phoneState.app=zone==='pc'?'browser':'home';}if(zone==='pc'&&['home','java','campus','sms','contacts'].includes(phoneState.app))phoneState.app='browser';if(zone==='phone'&&!phoneAppAllowed(phoneState.app))phoneState.app='home';navigate({type:'home'},false);if(phoneState.app==='books'&&phoneState.book){const id=phoneState.book;ensureBook(id).then(()=>{if(experienceZone===zone&&phoneState.app==='books'&&phoneState.book===id)refreshPhone();}).catch(()=>{});}return true;}
function renderExperienceLobby(){return `<main class="experience-home">
<header class="lobby-masthead"><button class="lobby-wordmark" data-experience="" aria-label="旧日时光首页"><span class="lobby-logomark">旧</span><span class="lobby-brand-copy"><b>旧日未关机</b><small>OLDDAYS / 记忆没有关机</small></span></button><div class="lobby-header-actions"><button class="lobby-era" data-action="date" aria-label="更改年代"><span>重访</span> ${year()} <span>⌄</span></button><button data-save-open class="experience-save" aria-label="我的存档">存档</button><button class="lobby-settings" data-action="settings" aria-label="界面设置">⚙</button></div></header>
<section class="lobby-intro"><div><span class="lobby-edition">献给那些舍不得关机的夜晚</span><h1>那时候，<br>天亮了才舍得睡<span>。</span></h1><p>一格电，一首循环的歌，一条等了很久的消息。<br>那些回不去的日子，还在这里亮着。</p></div><div class="lobby-stamp"><span>记忆没有关机</span><b>20<span>:</span>04</b><small>NO SIGNAL. JUST MEMORIES.</small></div></section>
<section class="experience-cards" aria-label="选择一种旧时光">
<button class="lobby-card lobby-pocket" data-experience="phone"><div class="lobby-art"><span class="lobby-card-index">01 / 随身收藏</span><div class="lobby-phone-note">电量不多了<br>再玩一局。</div><img src="images/references/nokia-n73-real.jpg" alt="经典 Nokia N73 实机" loading="eager"><span class="lobby-sticker">还剩一格电</span></div><div class="lobby-card-copy"><small>POCKET MEMORIES</small><h2>把青春握在手里<span>↗</span></h2><p>旧手机 · 游戏 · 音乐 · 被窝里的小说</p><b>口袋时光 <span>拿起手机 →</span></b></div></button>
<button class="lobby-card lobby-internet" data-experience="pc"><div class="lobby-art"><span class="lobby-card-index">02 / 拨号重连</span><div class="lobby-crt"><div class="lobby-crt-screen"><div>Internet Explorer <span>×</span></div><small>http://www.2004.com</small><strong>世界很大。<br>网速很慢。</strong><p>新闻　论坛　聊天室<br>欢迎回到互联网的夏天</p><i>正在连接… ▰▰▰▱▱</i></div><span class="lobby-crt-brand">PERSONAL COMPUTER　●</span></div><div class="lobby-keyboard">▥ ▥ ▥ ▥ ▥ ▥ ▥ ▥ ▥ ▥ ▥ ▥</div></div><div class="lobby-card-copy"><small>BACK ONLINE</small><h2>再上一会儿网<span>↗</span></h2><p>年度新闻 · 旧网址 · 论坛与个人主页</p><b>重连旧网 <span>连接旧世界 →</span></b></div></button>
<button class="lobby-card lobby-story" data-experience="story"><div class="lobby-art"><img src="images/shop/oldlane-interior.jpg" alt="雨夜里还亮着灯的旧手机修理铺" loading="eager"><span class="lobby-card-index">03 / 雨夜来客</span><span class="lobby-story-sign">旧巷手机修理铺<br><small>营业中 / 请推门</small></span><span class="lobby-story-sub">有人把秘密，留在了旧手机里。</span></div><div class="lobby-card-copy"><small>STORIES LEFT BEHIND</small><h2>今晚，你来守店<span>↗</span></h2><p>翻找旧物 · 收到短信 · 拼起陌生人的人生</p><b>旧巷来客 <span>推开玻璃门 →</span></b></div></button>
</section><section class="lobby-afterhours"><span><i>●</i> 今晚的消遣 <small>不用赶时间，随便逛逛。</small></span><nav aria-label="快速开始"><button data-lobby-app="games">✣ 再玩一局</button><button data-lobby-app="music">♫ 听首老旋律</button><button data-lobby-app="books">书 被窝里读一章</button><button data-lobby-app="magazines">▤ 翻翻旧杂志</button></nav></section><footer class="lobby-footer"><span>旧日 · 把过去，再过一遍。</span><span>三种体验，分别存档。随时回来。</span></footer></main>`;}
function renderExperienceHome(){if(!experienceZone)return renderExperienceLobby();const nav=experienceNav();if(experienceZone==='story')return nav+(deskEntered?zoneStoryWorkbench():zoneStoryEntrance().replace(/<details class="oldlane-museum">[\s\S]*<\/details>/,''));if(experienceZone==='pc')return nav+renderPcWorkbench();const modelId={symbian:'silver',n73:'black',nokia5230:'white'}[phoneState.model]||(typeof blenderHandsets!=='undefined'&&blenderHandsets[phoneState.model]?phoneState.model:'');return nav+(deskEntered?(modelId?'<div class="experience-phone-tools"><button data-experience-handset="'+modelId+'">拿起这部 3D 手机</button><span>旋转机身、按实体键；普通游玩</span></div>':'')+renderPhoneLab().replace('返回浏览器首页','返回总入口'):zoneResourceShelf()+zonePicker());}
setVisitMode=function(mode){return chooseExperience(mode==='pc'?'pc':'phone');};
const zoneTideOpen=tideOpenDevice;
tideOpenDevice=function(id){if(experienceZone!=='story'){experienceSave();experienceZone='story';visitMode='phone';[tide.active,campus.started,mystery.started,mystery.paused]=zoneStoryFlags;}return zoneTideOpen(id);};
phoneScreen=function(){if(experienceZone==='story')return zoneScreen();const flags=[tide.active,campus.started,mystery.started,campus.solved];tide.active=false;campus.started=false;mystery.started=false;campus.solved=false;try{return zoneScreen();}finally{[tide.active,campus.started,mystery.started,campus.solved]=flags;}};
const zoneAllowed=phoneAppAllowed,zoneInstalled=installedSystemApps,zoneSms=phoneSmsMarkup;
phoneAppAllowed=function(app){return !(experienceZone!=='story'&&app==='campus')&&zoneAllowed(app);};
installedSystemApps=function(){return zoneInstalled().filter(a=>phoneAppAllowed(a.id));};
phoneSmsMarkup=function(){return experienceZone==='story'?zoneSms():mysteryBaseSms();};
const zoneBrowser=phoneUCMarkup;
phoneUCMarkup=function(){if(experienceZone!=='pc')return zoneBrowser();return '<section class="pc-browser-page">'+(ucContent?'<button data-uc-back>‹ 返回导航</button>'+ucRenderedContent():'<header><small>INTERNET / '+year()+'</small><h1>欢迎回到 '+year()+' 年的互联网。</h1><p>输入旧网址，翻翻论坛和当年的网页。</p></header><form data-uc-search><input name="query" aria-label="电脑站内搜索" placeholder="搜索网站、新闻、小说" value="'+escapeHTML(ucQuery)+'"><button>搜索</button></form><h2>网址收藏夹</h2>'+ucWebsiteDirectory())+'</section>';};
function zoneResourceShelf(){return '<section class="zone-resource-shelf"><h2>随便玩玩，从这里开始</h2><nav>'+[['games','游戏厅 / 战棋与冒险'],['music','音乐 / 彩铃与旋律'],['books','小说 / 夜读书架'],['magazines','杂志 / 漫画翻页']].map(([id,t])=>'<button data-phone-app="'+id+'">'+t+'</button>').join('')+'</nav><p>'+Object.keys(phoneModels).length+' 款设备 · '+(pocketJavaGames.length+pocketClassicGames.length)+' 款口袋游戏 · '+memoryTracks.length+' 首年代歌单 · '+kioskAvailable().length+' 个报刊入口</p></section>';}
document.addEventListener('click',e=>{const quick=e.target.closest('[data-lobby-app]');if(quick){e.preventDefault();const app=quick.getAttribute('data-lobby-app');if(!['games','music','books','magazines'].includes(app))return;chooseExperience('phone');deskEntered=true;phoneState.app=app;phoneState.book=null;savePhone();navigate({type:'home'},false);return;}if(e.target.closest('[data-tide-view="native"]')){e.preventDefault();e.stopImmediatePropagation();return chooseExperience('phone');}const hand=e.target.closest('[data-experience-handset]');if(hand){e.preventDefault();return openBlenderWorld('phone',hand.getAttribute('data-experience-handset'));}const b=e.target.closest('[data-experience]');if(b){e.preventDefault();return chooseExperience(b.getAttribute('data-experience'));}if(e.target.closest('[data-action="home"]')){experienceSave();experienceZone='';}},true);
window.addEventListener('pagehide',experienceSave);

// Keep the live model and its screen alive when an app refreshes the page shell.
function pocketModelId(){return {symbian:'silver',n73:'black',nokia5230:'white'}[phoneState.model]||phoneState.model;}
function mountPocketModel(retained){
 const native=document.querySelector('#museum-device');
 if(experienceZone!=='phone'||!deskEntered||!native||typeof document.createElement!=='function')return;
 native.classList.add('pocket-native-bridge');
 const host=document.createElement('section');host.id='pocket-model-host';host.setAttribute('aria-label','可操作的三维设备');native.before(host);
 if(retained){host.append(retained);if(blenderWorld?.powered){blenderWorld.reclaim?.();refreshPhone();}blenderWorld?.draw?.();}
 else {const app=phoneState.app;openBlenderWorld('phone',pocketModelId(),host).then(()=>{if(blenderWorld?.inline&&!blenderWorld.failed){blenderWorld.startApp=app;blenderWorld.power();}});}
}
function retainPocketModel(page){
 const active=blenderWorld?.inline;
 const keep=active&&experienceZone==='phone'&&deskEntered&&page.type==='home'&&blenderWorld.device===pocketModelId();
 const retained=keep?document.querySelector('#pocket-model-host > .shop3d'):null;
 if(retained)retained.remove();else if(active)blenderWorldDispose?.();
 return retained;
}
